// config.js —— 全局常量与武器/敌人参数表
// 集中管理数值，便于后续平衡性调整

const CONFIG = {
  // ---- 渲染 ----
  fov: 75,
  fovPortrait: 88,          // 竖屏水平视野补偿（竖屏 aspect<1，垂直 FOV 需加大才不会太窄）
  renderDistance: 1000,
  shadowMapSize: 1024,      // 阴影贴图分辨率（2048→1024，手机阴影开销大）

  // ---- 玩家 ----
  player: {
    height: 1.7,            // 站立眼高
    radius: 0.35,           // 碰撞半径
    walkSpeed: 7.5,         // m/s
    runSpeed: 11,           // 加速跑（未实装，留接口）
    crouchSpeed: 3.5,
    jumpVelocity: 7.2,
    gravity: 22,
    accelGround: 14,        // 地面加减速
    accelAir: 2.4,          // 空中控制（CS 空中转向受限）
    friction: 9,
    maxHealth: 100,
    maxArmor: 100,
    mouseSensitivity: 0.0022,
    touchSensitivity: 0.008,   // 触屏灵敏度（约为鼠标的 3.6 倍，手指拖拽需更快响应）
  },

  // ---- 武器定义 ----
  // type: semi(半自动) / auto(全自动)
  // spread: 弹道散布角度(弧度)；
  weapons: {
    usp: {
      id: 'usp', name: 'USP', slot: 1,
      type: 'semi',
      damage: 24, headMult: 4, legMult: 0.75, armMult: 1, gunMult: 0.5,
      fireRate: 0.16,       // 最小开火间隔(秒)
      magSize: 12, reserve: 60,
      reloadTime: 1.6,
      spread: 0.008, spreadMove: 0.05,
      recoil: { x: 0.012, y: 0.018 },   // 后坐力(向上/左右抖动)
      range: 200,
      autoReload: true,
    },
    ak47: {
      id: 'ak47', name: 'AK-47', slot: 2,
      type: 'auto',
      damage: 30, headMult: 4, legMult: 0.75, armMult: 1, gunMult: 0.5,
      fireRate: 0.099,
      magSize: 30, reserve: 90,
      reloadTime: 2.4,
      spread: 0.012, spreadMove: 0.07,
      recoil: { x: 0.020, y: 0.028 },
      range: 250,
      autoReload: true,
    },
  },

  // ---- 敌人 ----
  enemy: {
    radius: 0.4,
    height: 1.8,
    maxHealth: 100,
    moveSpeed: 3.2,
    chaseSpeed: 4.6,
    fireRange: 45,
    fireInterval: 0.7,      // 开火间隔
    burstCount: 3,          // 一次点射击数
    burstDelay: 0.12,
    damage: 8,              // 每发对玩家伤害
    hitChance: 0.45,        // 命中率(玩家在视野内时)
    sightRange: 70,
    fov: Math.PI * 0.55,    // 视野半角
    reactionTime: 0.35,     // 发现玩家到开火延迟
  },

  // ---- 回合 ----
  waves: [
    { count: 3,  hp: 80,  speed: 2.8 },
    { count: 4,  hp: 100, speed: 3.2 },
    { count: 5,  hp: 100, speed: 3.6 },
    { count: 6,  hp: 120, speed: 4.0 },
    { count: 8,  hp: 140, speed: 4.4 },
  ],

  // ---- 血包 ----
  pickup: {
    healAmount: 50,         // 每次回血量
    pickupRadius: 1.4,      // 拾取半径（米）
    respawnTime: 15,        // 拾取后重生秒数
    // 固定点位 [x, z]，均避开墙体/掩体与出生点
    spawns: [
      [0, 3.4],      // 中央长廊（中央木箱旁）
      [-10, 8],      // 上半区 CT 侧
      [18, -8],      // 下半区 T 侧
      [-20, -6],     // 下半区 CT 出生区旁
    ],
  },
};

// 工具：限制范围
const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
const lerp = (a, b, t) => a + (b - a) * t;

// 经典脚本全局暴露（依赖顺序：config 最先加载，后续脚本通过 window 命名空间取用）
window.CONFIG = CONFIG;
window.clamp = clamp;
window.lerp = lerp;
